// 1. Safely extract the incoming data wrapper
const incomingJson = $input.item.json;
const payload = incomingJson.body || incomingJson; 

// 2. Safely grab the date and cycle length
const periodStartStr = payload.periodStartDate || payload.lastPeriodDate || payload.period_start_date;
const cycleLength = parseInt(payload.cycleLength || payload.cycle_length) || 28;

// DEBUG FLAG: If no date was found at all, return a helpful error message instead of crashing
if (!periodStartStr) {
  return {
    json: {
      error: "No starting date found in payload!",
      whatN8nReceived: incomingJson,
      conceptionRisk: "Unknown",
      message: "Please check your field names in Lovable."
    }
  };
}

// 3. Setup today's date
const today = new Date();
today.setHours(0, 0, 0, 0);

// 4. Handle date parsing securely whether it uses '/' or '-'
let lastPeriod;
if (periodStartStr.includes('/')) {
  const dateParts = periodStartStr.split('/');
  const day = parseInt(dateParts[0], 10);
  const month = parseInt(dateParts[1], 10) - 1; 
  const year = parseInt(dateParts[2], 10);
  lastPeriod = new Date(year, month, day);
} else {
  lastPeriod = new Date(periodStartStr); // Fallback for standard YYYY-MM-DD
}
lastPeriod.setHours(0, 0, 0, 0);

// 5. Run the calculations
const ovulationDay = new Date(lastPeriod);
ovulationDay.setDate(lastPeriod.getDate() + (cycleLength - 14));

const fertileWindowStart = new Date(ovulationDay);
fertileWindowStart.setDate(ovulationDay.getDate() - 5);

const fertileWindowEnd = new Date(ovulationDay);
fertileWindowEnd.setDate(ovulationDay.getDate() + 1);

let safetyStatus = "Low"; 
let message = "You are currently in a low-risk window. Enjoy your peace of mind!";

if (today >= fertileWindowStart && today <= fertileWindowEnd) {
  safetyStatus = "High";
  message = "You are inside your fertile window. High risk of conception! Protect yourself.";
}

const formatDate = (d) => {
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

// 6. Send output data back
return {
  json: {
    conceptionRisk: safetyStatus,
    fertileStart: formatDate(fertileWindowStart),
    fertileEnd: formatDate(fertileWindowEnd),
    ovulationDate: formatDate(ovulationDay),
    message: message
  }
};

