async function run() {
  // 1. Specify the item index (0 for the first item) and binary property name ('data')
  // This resolves the reference to the actual binary buffer
  const binaryDataBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');

  // 2. Convert the buffer to a Base64 string
  const base64Audio = binaryDataBuffer.toString('base64');

  // 3. Return the bundled JSON with the encoded audio
  return {
    json: {
      ...$('AI Agent').first().json.output,
      audioBase64: base64Audio,
      audioMimeType: 'audio/mp3' 
    }
  };
}

return await run();
